/**
 * End-to-end guard for the MINUS-to-anti-join rewrite: a MINUS operand whose FILTER or sub-select references a variable
 * that is only in scope on the left-hand side must keep MINUS semantics whether the packed planner keeps the Difference
 * or rewrites it to a {@code minus-assured-shared} anti-join, cold and after plan caching has kicked in.
 */
class LmdbMinusAntiJoinSemanticsTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	static Stream<Arguments> shapes() {
		String filterBody = "MINUS { ?s :q ?v FILTER(?v = ?o) }";
		String subSelectBody = "MINUS { SELECT ?s WHERE { ?s :q ?o } }";
		String sharedBody = "MINUS { ?s :q ?o }";
		return Stream.of(
				Arguments.of(filterBody, 4), Arguments.of(filterBody, 400),
				Arguments.of(subSelectBody, 4), Arguments.of(subSelectBody, 400),
				Arguments.of(sharedBody, 4), Arguments.of(sharedBody, 400));
	}

	@ParameterizedTest(name = "{0} rows={1}")
	@MethodSource("shapes")
	void minusOperandReferencingLeftOnlyVariableKeepsMinusSemantics(String minusClause, int rows,
			@TempDir File dataDir) {
		IRI p = VF.createIRI("urn:ex:p");
		IRI q = VF.createIRI("urn:ex:q");
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try {
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < rows; i++) {
					IRI subject = VF.createIRI("urn:ex:s" + i);
					IRI object = VF.createIRI("urn:ex:o" + i);
					connection.add(subject, p, object);
					if (i % 4 == 0) {
						// the q-edge reuses the left object: NOT EXISTS substitution would match it
						connection.add(subject, q, object);
					} else if (i % 4 == 2) {
						// the q-edge points elsewhere: only an uncorrelated MINUS operand sees it
						connection.add(subject, q, VF.createIRI("urn:ex:other" + i));
					}
				}
				connection.commit();

				String query = "PREFIX : <urn:ex:>\nSELECT ?s ?o WHERE { ?s :p ?o " + minusClause + " }";
				// FILTER body: ?o is unbound inside the operand, so the operand is empty and nothing is removed.
				// Sub-select body: the operand is {?s | ?s :q ?anything}, so every even subject is removed.
				// Shared body: only subjects whose q-edge reuses the object (i % 4 == 0) are removed.
				int expected;
				if (minusClause.contains("SELECT")) {
					expected = rows / 2;
				} else if (minusClause.contains("FILTER")) {
					expected = rows;
				} else {
					expected = rows - (rows + 3) / 4;
				}
				for (int run = 0; run < 3; run++) {
					int actual = 0;
					try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
						while (result.hasNext()) {
							result.next();
							actual++;
						}
					}
					int observed = actual;
					int attempt = run;
					assertEquals(expected, observed,
							() -> "run " + attempt + "\n" + connection.prepareTupleQuery(query)
									.explain(Explanation.Level.Optimized));
				}
			}
		} finally {
			repository.shutDown();
		}
	}
}
